quiz.answer:
declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

interface User {
  id: number;
  name: string;
  nickname?: string;
}

function displayName(user: User): string {
  if (user.nickname) {
    return user.nickname;
  }
  return user.name;
}

for (const line of lines) {
  const [id, name, nickname] = line.split(",");
  const user: User = nickname ? { id: Number(id), name, nickname } : { id: Number(id), name };
  console.log(`${user.id}: ${displayName(user)}`);
}

