quiz.answer:
declare const require: any; // 標準入力を読むための宣言(消さない)
const input: string = require("fs").readFileSync(0, "utf8");
const lines: string[] = input.split("\n").filter((l: string) => l.trim() !== "");

interface User {
  id: number;
  name: string;
}

function findName(users: User[], id: number): string {
  for (const user of users) {
    if (user.id === id) {
      return user.name;
    }
  }
  return "見つかりません";
}

const target = Number(lines[0]);
const users: User[] = lines.slice(1).map((line) => {
  const [id, name] = line.split(",");
  return { id: Number(id), name };
});
console.log(findName(users, target));
